#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-browser-validation-receipt.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-browser-validation-receipt — refuses a browser_validated stamp whose
 * manual-results record is not a valid WALKER-SIGNED walk (BROWSER_VALIDATION.yaml.evidence).
 *
 * The gap this closes: verify-standards-compliance already checks a
 * browser_validated feature HAS a manual-results/<flow>.<iso>.json record with a
 * fresh mtime — but it never reads the record's CONTENT. So a hand-written stub
 * (an empty `{}` with the right filename and a fresh timestamp) passes, and the
 * stamp becomes a lie about a walk that never happened.
 *
 * What it checks — for every feature whose standards-compliance.yaml carries a
 * real browser_validated timestamp, for the newest record of each declared flow:
 *   1. the record is valid JSON,
 *   2. it carries a VALID walker SIGNATURE (_walker-receipt.mjs) — the record went
 *      through the walker's keyed signing routine and has not been edited since
 *      (tamper-evidence: flipping ok, backdating, or swapping findings breaks it),
 *   3. `ok === true` (a stamp whose latest verdict is ok:false is a contradiction —
 *      the walk failed but the lock was stamped),
 *   4. `observed` is a non-empty per-step array where every entry carries a verdict
 *      (a signed-but-empty walk is not a walk).
 *
 * Scope / honesty: the signature proves the record was produced by the walker
 * signing path and is un-tampered — it does NOT prove a browser actually rendered
 * (a session deliberately signing fabricated observations would pass; the key is
 * machine-local). True walk-provenance needs the Chrome extension to emit the
 * receipt itself — the ceiling, outside ~/.claude. Record EXISTENCE + freshness
 * stay owned by verify-standards-compliance; this gate owns record CONTENT +
 * SIGNATURE only. Signature verification runs only where records exist (local);
 * in CI (records git-ignored) the gate no-ops per record (ci_split).
 *
 * No-op green when no feature carries a browser_validated stamp.
 *
 * Usage: node scripts/verify/verify-browser-validation-receipt.mjs [<repo-root>]
 * Exits 0 when every stamped feature's newest records are valid signed walks (or none exist); 1 otherwise.
 */
import { readdirSync, readFileSync, statSync, existsSync } from "node:fs";
import { join, relative, dirname } from "node:path";
import { verifyReceipt, loadKey } from "./_walker-receipt.mjs";

const REPO_ROOT = process.argv[2] || process.cwd();
const NAME = "verify-browser-validation-receipt";
const IGNORE = new Set(["node_modules", ".git", ".next", ".turbo", "dist", "build", "out", "coverage", ".vercel"]);
const WALKER_KEY = loadKey();

function walk(dir, match, acc = []) {
  let entries;
  try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return acc; }
  for (const e of entries) {
    if (IGNORE.has(e.name)) continue;
    const p = join(dir, e.name);
    if (e.isDirectory()) walk(p, match, acc);
    else if (e.isFile() && match(e.name, p)) acc.push(p);
  }
  return acc;
}

// browser_validated value from a standards-compliance.yaml (regex; avoids a YAML dep).
function browserValidatedValue(text) {
  const m = text.match(/^\s*browser_validated\s*:\s*["']?([^"'\n#]+)["']?/m);
  if (!m) return null;
  const v = m[1].trim();
  if (!v || /^(n\/a|not[-_ ]?required|false|null|~)$/i.test(v)) return null;
  return v;
}

// Walk up from startDir (bounded by REPO_ROOT's parent) to find a manual-results dir.
function findResultsDir(startDir) {
  let dir = startDir;
  for (let i = 0; i < 8; i++) {
    const cand = join(dir, "manual-results");
    if (existsSync(cand)) return cand;
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

function newestRecord(resultsDir, stem) {
  let files;
  try { files = readdirSync(resultsDir).filter((f) => f.startsWith(`${stem}.`) && f.endsWith(".json")); } catch { return null; }
  let best = null, bestMs = -1;
  for (const f of files) {
    const p = join(resultsDir, f);
    let ms = 0;
    try { ms = statSync(p).mtimeMs; } catch { continue; }
    if (ms > bestMs) { bestMs = ms; best = p; }
  }
  return best;
}

function validateRecord(file) {
  let raw;
  try { raw = readFileSync(file, "utf8"); } catch { return "record unreadable"; }
  let obj;
  try { obj = JSON.parse(raw); } catch { return "record is not valid JSON"; }
  if (obj === null || typeof obj !== "object" || Array.isArray(obj)) return "record is not a JSON object";
  // Signature — the record must be a valid, un-tampered walker receipt.
  const sig = verifyReceipt(obj, WALKER_KEY);
  if (!sig.ok) return sig.reason;
  // ok must be true (a signed FAILED walk cannot back a browser_validated stamp).
  if (obj.ok !== true) return "record `ok` is false — the walk FAILED but the lock was stamped browser_validated";
  // observed must be a non-empty per-step array with verdicts (a signed-but-empty walk is not a walk).
  if (!Array.isArray(obj.observed) || obj.observed.length === 0) return "signed record has no `observed` steps — an empty walk is not a walk";
  const everyStepJudged = obj.observed.every((s) => s && typeof s === "object" && typeof s.verdict === "string" && s.verdict.trim());
  if (!everyStepJudged) return "at least one `observed` step has no verdict — the walk is incomplete";
  return null;
}

const compFiles = walk(REPO_ROOT, (name) => name === "standards-compliance.yaml");
let stampedFeatures = 0;
const violations = [];

for (const comp of compFiles) {
  let text = "";
  try { text = readFileSync(comp, "utf8"); } catch { continue; }
  if (!browserValidatedValue(text)) continue;
  stampedFeatures++;
  const specsDir = dirname(comp);                    // .../__specs__
  const featureDir = dirname(specsDir);
  const manualDir = join(specsDir, "manual");
  if (!existsSync(manualDir)) continue;              // no flows declared; existence owned elsewhere
  let stems = [];
  try { stems = readdirSync(manualDir).filter((f) => f.endsWith(".md")).map((f) => f.slice(0, -3)); } catch { stems = []; }
  const resultsDir = findResultsDir(featureDir);
  if (!resultsDir) continue;                          // no records dir; existence owned by verify-standards-compliance
  for (const stem of stems) {
    const rec = newestRecord(resultsDir, stem);
    if (!rec) continue;                               // missing record owned by verify-standards-compliance
    const problem = validateRecord(rec);
    if (problem) violations.push(`${relative(REPO_ROOT, rec)} (flow "${stem}"): ${problem}`);
  }
}

if (stampedFeatures === 0) {
  process.stdout.write(`✅ ${NAME} — no browser_validated stamps in this repo; nothing to gate.\n`);
  process.exit(0);
}
if (violations.length === 0) {
  process.stdout.write(`✅ ${NAME} — ${stampedFeatures} stamped feature(s); every checked walk record is real.\n`);
  process.exit(0);
}
process.stderr.write(`\n❌ ${NAME}: ${violations.length} stub/invalid walk-record violation(s)\n`);
for (const v of violations) process.stderr.write(`   - ${v}\n`);
process.stderr.write(`\n   A browser_validated stamp requires a real walk record (ok:true + findings/steps). BROWSER_VALIDATION.yaml.evidence.\n`);
process.exit(1);
